const writing=['Should universities give greater weight to potential than demonstrated attainment?','Is it ever reasonable to limit individual choice for the benefit of society?','Does technological progress necessarily improve education?'];
const exams={ESAT:{description:'Engineering and Science Admissions Test',format:'27 questions · 40 minutes per module',modules:['Mathematics 1','Mathematics 2','Physics','Chemistry','Biology'],count:27,time:40},TMUA:{description:'Test of Mathematics for University Admission',format:'20 questions · 75 minutes per paper',modules:['Paper 1','Paper 2'],count:20,time:75},TARA:{description:'Test of Academic Reasoning for Admissions',format:'22 questions · 40 minutes per MCQ module',modules:['Critical Thinking','Problem Solving','Writing Task'],count:22,time:40}};
const app=document.querySelector('#app');let state={};const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},save=(k,v)=>localStorage.setItem(k,JSON.stringify(v)),history=()=>read('axiom-history',[]),mistakes=()=>read('axiom-mistakes',[]);
function active(v){document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===v))}
function go(v){clearInterval(state.timer);active(v);({home,progress,resources,mistakes:mistakeBook}[v]||home)()}
function home(){document.body.classList.remove('testing');const h=history(),avg=h.length?Math.round(h.reduce((s,x)=>s+x.score,0)/h.length):0;app.innerHTML=`<section class="hero"><div><div class="eyebrow">Computer-based admissions test practice</div><h1>Choose a practice test</h1><p>Familiarise yourself with official timing, question navigation and review tools while working through original English-language questions.</p></div><div class="summary"><div><span>Sessions completed</span><b>${h.length}</b></div><div><span>Average accuracy</span><b>${avg}%</b></div></div></section><section class="grid">${Object.entries(exams).map(([n,e])=>`<article class="exam"><div class="exam-title"><div class="eyebrow">Practice test</div><h2>${n}</h2></div><div class="exam-body"><p>${e.description}</p><div class="format">${e.format}</div><div class="chips">${e.modules.map(m=>`<span class="chip">${m}</span>`).join('')}</div><button class="start" data-setup="${n}">Set up practice test</button></div></article>`).join('')}</section><div class="note"><b>Practice notice:</b> Official UAT-UK preparation links are available under Resources. Questions answered on this independent platform are original.</div>`;document.querySelectorAll('[data-setup]').forEach(b=>b.onclick=()=>setup(b.dataset.setup))}
function setup(n){const e=exams[n];app.innerHTML=`<section class="setup"><button class="backlink" data-view="home">← Back to tests</button><div class="eyebrow">${n} SESSION BUILDER</div><h1>Build your practice set</h1><div class="setup-grid"><div><label>Module</label><select id="module">${e.modules.map(m=>`<option>${m}</option>`).join('')}</select></div><div><label>Mode</label><select id="mode"><option value="practice">Practice — 10 questions</option><option value="quick">Quick drill — 5 questions</option><option value="full">Full simulation — official timing</option></select></div><div><label>Topic</label><select id="topic"></select></div><div><label>Question order</label><select id="order"><option value="random">Randomised</option><option value="fixed">Bank order</option></select></div></div><div id="session" class="session-card"></div><button id="begin" class="primary">Begin session</button></section>`;const m=document.querySelector('#module'),mode=document.querySelector('#mode'),topic=document.querySelector('#topic');function refresh(){const ts=[...new Set(bank.filter(x=>x.exam===n&&x.module===m.value).map(x=>x.topic))],old=topic.value;topic.innerHTML='<option value="all">All topics</option>'+ts.map(t=>`<option>${t}</option>`).join('');if(ts.includes(old))topic.value=old;const a=bank.filter(x=>x.exam===n&&x.module===m.value).length,w=mode.value==='quick'?5:mode.value==='full'?e.count:10;document.querySelector('#session').innerHTML=`<b>${m.value}</b><span>${Math.min(w,a)} currently available question(s) · ${mode.value==='full'?e.time+' minutes':'review-friendly mode'}</span>${w>a?'<small>Official timing is used; the independent question bank is still growing.</small>':''}`}m.onchange=refresh;mode.onchange=refresh;refresh();document.querySelector('#begin').onclick=()=>begin(n,m.value,topic.value,mode.value,document.querySelector('#order').value);bind()}
function begin(exam,module,topic,mode,order){if(module==='Writing Task'){writeTask(mode);return}let qs=bank.filter(x=>x.exam===exam&&x.module===module&&(topic==='all'||x.topic===topic));if(order==='random')qs=[...qs].sort(()=>Math.random()-.5);const want=mode==='quick'?5:mode==='full'?exams[exam].count:10;qs=qs.slice(0,want);state={exam,module,index:0,questions:qs,answers:Array(qs.length).fill(null),flags:Array(qs.length).fill(false),seconds:mode==='full'?exams[exam].time*60:0,mode,timer:null};renderTest();if(mode==='full')state.timer=setInterval(()=>{state.seconds--;const t=document.querySelector('.timer');if(t)t.textContent=clock(state.seconds);if(state.seconds<=0)finish()},1000)}
const clock=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;
function renderTest(){document.body.classList.add('testing');const x=state.questions[state.index],answered=state.answers.filter(a=>a!==null).length;app.innerHTML=`<div class="test-app"><div class="testbar"><div class="test-name">${state.exam}<small>${state.module} · Practice test</small></div><button class="tool" id="help"><span class="tool-icon">?</span><span class="tool-label">Help</span></button><button class="tool" id="exit"><span class="tool-icon">×</span><span class="tool-label">Exit</span></button><div class="timebox"><small>${state.mode==='full'?'Time remaining':'Session mode'}</small><span class="timer">${state.mode==='full'?clock(state.seconds):'PRACTICE'}</span></div></div><div class="test-shell"><section class="paper"><div class="question-head"><span class="qmeta">Question ${state.index+1} of ${state.questions.length}</span><span class="qstate">${x.topic} · ${answered} answered</span></div><div class="question-body"><h1 class="question">${x.prompt}</h1><div class="options">${x.options.map((o,i)=>`<button class="option ${state.answers[state.index]===i?'selected':''}" data-answer="${i}"><span class="letter">${'ABCD'[i]}</span><span class="option-text">${o}</span></button>`).join('')}</div></div><div class="controls"><button class="secondary" id="prev" ${state.index===0?'disabled':''}>← Previous</button><button class="secondary review-btn ${state.flags[state.index]?'active':''}" id="flag">⚑ ${state.flags[state.index]?'Remove review flag':'Flag for review'}</button><button class="primary next" id="next">${state.index===state.questions.length-1?'Review questions':'Next →'}</button></div></section><aside class="side"><h3>Question navigator</h3><div class="qgrid">${state.questions.map((_,i)=>`<button class="qnum ${state.answers[i]!==null?'done':''} ${state.flags[i]?'flag':''} ${i===state.index?'current':''}" data-q="${i}">${i+1}</button>`).join('')}</div><div class="legend"><span class="key"><i class="swatch answered"></i>Answered</span><span class="key"><i class="swatch"></i>Not answered</span><span class="key"><i class="swatch review"></i>Flagged for review</span></div><button class="start finish" id="finish">End test</button></aside></div></div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{state.answers[state.index]=+b.dataset.answer;renderTest()});document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{state.index=+b.dataset.q;renderTest()});document.querySelector('#prev').onclick=()=>{if(state.index){state.index--;renderTest()}};document.querySelector('#flag').onclick=()=>{state.flags[state.index]=!state.flags[state.index];renderTest()};document.querySelector('#next').onclick=()=>{state.index=Math.min(state.questions.length-1,state.index+1);renderTest()};document.querySelector('#finish').onclick=finish;document.querySelector('#exit').onclick=()=>go('home');document.querySelector('#help').onclick=()=>alert('Select one answer for each question. Use the navigator to move between questions and flag any question you want to review.')}
function finish(){clearInterval(state.timer);const c=state.questions.filter((x,i)=>x.answer===state.answers[i]).length,score=Math.round(c/state.questions.length*100),h=history();h.push({exam:state.exam,module:state.module,score,total:state.questions.length,date:new Date().toISOString()});save('axiom-history',h);const wrong=mistakes();state.questions.forEach((x,i)=>{const p=wrong.indexOf(x.id);if(state.answers[i]!==x.answer&&p<0)wrong.push(x.id);if(state.answers[i]===x.answer&&p>=0)wrong.splice(p,1)});save('axiom-mistakes',wrong);app.innerHTML=`<section class="result"><div class="eyebrow">SESSION COMPLETE · ${state.exam}</div><h1>${score}%</h1><p class="result-lead">${c} of ${state.questions.length} correct. Missed questions were added to your mistake book.</p>${state.questions.map((x,i)=>review(x,state.answers[i],i)).join('')}<button class="primary" data-view="home">Return to practice</button></section>`;bind()}
function review(x,a,i){const ok=a===x.answer;return`<article class="review ${ok?'good':'bad'}"><div class="review-head"><b>Question ${i+1} · ${ok?'Correct':'Review'}</b><span>${x.topic}</span></div><p>${x.prompt}</p><p><strong>Your answer:</strong> ${a===null?'Not answered':`${'ABCD'[a]} · ${x.options[a]}`}</p><p><strong>Correct answer:</strong> ${'ABCD'[x.answer]} · ${x.options[x.answer]}</p><div class="explanation">${x.explanation}</div></article>`}
function mistakeBook(){const items=mistakes().map(id=>bank.find(x=>x.id===id)).filter(Boolean);app.innerHTML=`<div class="page-head"><div><div class="eyebrow">TARGETED REVIEW</div><h1>Mistake book</h1><p>Questions leave this list after a correct retry.</p></div><b>${items.length} saved</b></div>${items.length?`<div class="mistake-list">${items.map(x=>`<article class="mistake"><span>${x.exam} · ${x.module}</span><h3>${x.prompt}</h3><p>${x.topic}</p></article>`).join('')}</div><button id="retry" class="primary narrow">Retry all mistakes</button>`:'<div class="empty"><b>No mistakes saved</b><p>Missed questions will appear here.</p></div>'}`;if(items.length)document.querySelector('#retry').onclick=()=>{state={exam:'Mixed',module:'Mistake review',index:0,questions:items.sort(()=>Math.random()-.5),answers:Array(items.length).fill(null),flags:Array(items.length).fill(false),seconds:0,mode:'practice'};renderTest()}}
function progress(){const h=history();app.innerHTML=`<div class="page-head"><div><div class="eyebrow">YOUR PERFORMANCE</div><h1>Progress</h1><p>Stored only in this browser.</p></div><b>${h.length} sessions</b></div><section class="stats">${['ESAT','TMUA','TARA'].map(n=>{const a=h.filter(x=>x.exam===n),v=a.length?Math.round(a.reduce((s,x)=>s+x.score,0)/a.length):0;return`<div class="stat"><span>${n} average</span><b>${v}%</b><div class="bar"><i style="width:${v}%"></i></div><small>${a.length} session(s)</small></div>`}).join('')}</section><h2 class="section-title">Recent sessions</h2>${h.length?`<div class="history">${h.slice().reverse().map(x=>`<div><span><b>${x.exam}</b> · ${x.module}</span><span>${new Date(x.date).toLocaleDateString('en-GB')}</span><strong>${x.score}%</strong></div>`).join('')}</div>`:'<div class="empty"><b>No sessions yet</b></div>'}`}
function resources(){const copy={ESAT:'ESAT Guide for all five modules, specimen tests, and relevant historic ENGAA and NSAA papers.',TMUA:'Specification, Notes on Logic and Proof, specimen tests, and historic TMUA papers with worked answers.',TARA:'Specification, TARA Question Guide, two Pearson practice tests, plus recommended BMAT Section 1 and TSA archives.'};app.innerHTML=`<div class="page-head"><div><div class="eyebrow">OFFICIAL PREPARATION</div><h1>Recommended resources</h1><p>Direct links to UAT-UK. Open Pearson sample tests on desktop.</p></div></div><section class="resource-grid">${['ESAT','TMUA','TARA'].map(n=>`<article><div class="eyebrow">OFFICIAL UAT-UK</div><h2>${n}</h2><p>${copy[n]}</p><a href="${official[n]}" target="_blank" rel="noopener">Open ${n} materials ↗</a></article>`).join('')}</section><div class="note"><b>Recommended order:</b> specification → guide or notes → specimen test → timed practice test → recommended archives.</div><a class="all-resources" href="${official.prepare}" target="_blank" rel="noopener">View the complete preparation hub ↗</a>`}
function writeTask(mode){const prompt=writing[Math.floor(Math.random()*writing.length)];state.seconds=mode==='full'?2400:0;app.innerHTML=`<section class="writing"><div class="test-top"><b>TARA · Writing Task</b><span class="timer">${state.seconds?clock(state.seconds):'Practice mode'}</span></div><div class="qmeta">Develop a clear position with relevant reasoning. Maximum 750 words.</div><h1>${prompt}</h1><textarea id="essay" placeholder="Write your response here…"></textarea><div class="writing-foot"><span id="words">0 / 750 words</span><button class="primary narrow" id="complete">Complete task</button></div></section>`;const t=document.querySelector('#essay');t.oninput=()=>{let w=t.value.trim()?t.value.trim().split(/\s+/):[];if(w.length>750){t.value=w.slice(0,750).join(' ');w=w.slice(0,750)}document.querySelector('#words').textContent=`${w.length} / 750 words`};if(state.seconds)state.timer=setInterval(()=>{state.seconds--;document.querySelector('.timer').textContent=clock(state.seconds);if(state.seconds<=0)document.querySelector('#complete').click()},1000);document.querySelector('#complete').onclick=()=>{clearInterval(state.timer);app.innerHTML='<section class="result"><div class="eyebrow">WRITING TASK COMPLETE</div><h1>Review your response</h1><p class="result-lead">UAT-UK does not score this task. Check structure, clarity, evidence and counterarguments.</p><button class="primary" data-view="home">Return to practice</button></section>';bind()}}
const finishSession=finish;finish=function(){document.body.classList.remove('testing');return finishSession()}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=e=>{e.preventDefault();go(b.dataset.view)})}
bind();document.querySelector('#reset').onclick=()=>{if(confirm('Delete all locally stored progress and mistakes?')){localStorage.removeItem('axiom-history');localStorage.removeItem('axiom-mistakes');go('home')}};home();
